// Parsear respuesta de Claude — robusto a bloques thinking/text y a cambios de shape del nodo
const raw = $input.first().json.content;
let text = '';

if (typeof raw === 'string') {
  text = raw;
} else if (Array.isArray(raw)) {
  const textBlock = raw.filter(b => b && b.type === 'text').pop();
  text = textBlock ? textBlock.text : raw.map(b => (b && b.text) || '').join('');
}

if (!text) {
  throw new Error('Respuesta de Claude sin bloque de texto. Raw: ' + JSON.stringify($input.first().json).slice(0, 300));
}

// Sacar fences por las dudas y matchear el JSON
text = text.replace(/```json|```/g, '');
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('Claude no devolvió JSON válido. Raw: ' + text.slice(0, 200));

const data = JSON.parse(jsonMatch[0]);

// Fecha en TZ Argentina (toISOString devolvía fecha UTC)
data.fecha = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });

// Validaciones estructurales
if (!Array.isArray(data.top3) || data.top3.length !== 5) throw new Error('top3 inválido: ' + JSON.stringify(data.top3));
if (!Array.isArray(data.tendencias) || data.tendencias.length !== 3) throw new Error('tendencias inválido');
if (!data.resumen || !data.conclusion) throw new Error('Falta resumen o conclusion');

// Normalización y validación de enums
const CATEGORIAS = ['politica', 'economia', 'sociedad', 'internacional', 'geopolitica', 'ciencia', 'cultura', 'deportes', 'clima', 'tecnologia'];
const COBERTURAS = ['unanime', 'divergente', 'exclusiva'];
const normalizar = s => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

// Texto original de los artículos, para verificar que las URLs salgan del input
const articlesText = $('Formatear artículos').first().json.articles || '';

for (const item of data.top3) {
  item.categoria = normalizar(item.categoria);
  item.cobertura = normalizar(item.cobertura);
  if (!CATEGORIAS.includes(item.categoria)) throw new Error('categoria inválida: ' + item.categoria);
  if (!COBERTURAS.includes(item.cobertura)) throw new Error('cobertura inválida: ' + item.cobertura);

  if (typeof item.url !== 'string' || !/^https?:\/\//.test(item.url)) {
    throw new Error('URL inválida en top3: ' + item.url);
  }
  if (!articlesText.includes(item.url)) {
    throw new Error('URL no presente en el input (posible alucinación): ' + item.url);
  }

  // La imagen la llena el flujo con og:image, nunca el modelo
  item.imagen = '';
}

// alertas: string o null (tolerar array por las dudas)
if (Array.isArray(data.alertas)) data.alertas = data.alertas.join(' · ');
if (data.alertas === '' || data.alertas === 'null') data.alertas = null;

// Serializar data para pasarla a los nodos siguientes
return [{ json: { data } }];

// Separar las 5 URLs del top3 en items individuales para scrapear en paralelo
const data = $input.first().json.data;
const dataStr = JSON.stringify(data);

return data.top3.map((noticia, index) => ({
  json: {
    scrapeIndex: index,
    scrapeUrl: noticia.url,
    dataStr,
  }
}));

// Acceder a los items originales (con scrapeIndex y dataStr) usando el nodo anterior al scraping
const originalItems = $('Preparar scraping').all();
const scrapedItems = $input.all();

return scrapedItems.map((item, i) => {
  const original = originalItems[i].json;
  let ogImage = '';

  try {
    // item.json.data contiene el HTML cuando responseFormat es 'text'
    const html = (item.json.data || item.json.body || '') + '';

    // Intentar extraer og:image (y twitter:image como fallback)
    const match =
      html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i) ||
      html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["']/i) ||
      html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i) ||
      html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']twitter:image["']/i);

    if (match && match[1]) {
      ogImage = match[1].trim()
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'");
    }
  } catch (e) {
    // Scraping falló para este item — imagen queda vacía, no es bloqueante
  }

  return {
    json: {
      scrapeIndex: original.scrapeIndex,
      ogImage,
      dataStr: original.dataStr,
    }
  };
});

// Reconstruir el objeto data inyectando las imágenes scrapeadas
const imageResults = $input.first().json.imageResults;

// Todos los items tienen el mismo dataStr (los datos originales de Claude)
const data = JSON.parse(imageResults[0].dataStr);

// Inyectar imágenes por índice
imageResults.forEach(result => {
  if (result.ogImage) {
    data.top3[result.scrapeIndex].imagen = result.ogImage;
  }
});

// Preparar body para Upstash
data.actualizadoAt = new Date().toISOString();

const payload = JSON.stringify(data);
const upstashBody = JSON.stringify(['SET', 'noticias:diarias', payload, 'EX', '90000']);

// Preparar body para BD Postgres (snapshot histórico)
const snapshotBody = JSON.stringify({ kind: 'noticias-diarias', payload: data });

return [{ json: { upstashBody, snapshotBody, fecha: data.fecha } }];
